#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(3), b(3);
    for (int i = 0; i < 3; ++i) cin >> a[i];
    for (int i = 0; i < 3; ++i) cin >> b[i];

    vector<int> perm = {1, 2, 3, 4, 5, 6};
    vector<vector<int>> perms;
    do {
        perms.push_back(perm);
    } while (next_permutation(perm.begin(), perm.end()));

    int max_possible = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);
    int max_score = 0;

    for (auto &p : perms) {
        vector<int> a_copy = a;
        vector<int> b_copy = b;
        int score = 0;
        for (int el : p) {
            int t = 0;
            if (el == 1) {
                t = min(a_copy[0], b_copy[0]);
                a_copy[0] -= t;
                b_copy[0] -= t;
                score += t;
            } else if (el == 2) {
                t = min(a_copy[0], b_copy[2]);
                a_copy[0] -= t;
                b_copy[2] -= t;
                score += t;
            } else if (el == 3) {
                t = min(a_copy[1], b_copy[1]);
                a_copy[1] -= t;
                b_copy[1] -= t;
                score += t;
            } else if (el == 4) {
                t = min(a_copy[1], b_copy[0]);
                a_copy[1] -= t;
                b_copy[0] -= t;
                score += t;
            } else if (el == 5) {
                t = min(a_copy[2], b_copy[2]);
                a_copy[2] -= t;
                b_copy[2] -= t;
                score += t;
            } else if (el == 6) {
                t = min(a_copy[2], b_copy[1]);
                a_copy[2] -= t;
                b_copy[1] -= t;
                score += t;
            }
        }
        max_score = max(max_score, score);
    }

    cout << n - max_score << " " << max_possible << "\n";

    return 0;
}
